const fs = require('fs');
const path = require('path');

const DEFAULT_FILE = 'README.md';
const MARKER = 'TODO';

function countTodos(text) {
  const lines = text.split('\n');
  const perLine = [];
  let total = 0;

  lines.forEach((line, index) => {
    let count = 0;
    let from = 0;
    let at = line.indexOf(MARKER, from);
    while (at !== -1) {
      count += 1;
      total += 1;
      from = at + MARKER.length;
      at = line.indexOf(MARKER, from);
    }
    if (count > 0) {
      perLine.push({ line: index + 1, count, text: line.trim() });
    }
  });

  return { total, perLine };
}

function main() {
  const file = process.argv[2] || DEFAULT_FILE;
  const resolved = path.resolve(process.cwd(), file);

  let text;
  try {
    text = fs.readFileSync(resolved, 'utf8');
  } catch (err) {
    console.error(`Unable to read file: ${file}`);
    process.exit(1);
  }

  const { total, perLine } = countTodos(text);

  console.log(`File: ${file}`);
  console.log(`"${MARKER}" total: ${total}`);
  perLine.forEach((entry) => {
    console.log(`  line ${entry.line}: ${entry.count} - ${entry.text}`);
  });
}

main();

